package coordinator

const dashboardHTML = `<!doctype html><title>FORGER</title><style>body{font:14px system-ui;background:#0b1020;color:#e8edf8;margin:2rem}h1{color:#74d4ff}button{padding:.5rem;margin:.2rem}pre{background:#121b31;padding:1rem;overflow:auto}.grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem}</style><h1>FORGER <small>distributed object vault</small></h1><p><button onclick="act('scan')">Integrity scan</button><button onclick="act('repair')">Repair</button><button onclick="act('reconcile')">Reconcile</button><button onclick="act('rebalance')">Rebalance</button><button onclick="partition()">Toggle partition</button><button onclick="corrupt()">Corrupt replica</button></p><div class=grid><section><h2>Cluster</h2><pre id=cluster></pre></section><section><h2>Objects and replicas</h2><pre id=objects></pre></section><section><h2>Repair jobs</h2><pre id=repairs></pre></section><section><h2>Event timeline</h2><pre id=events></pre></section></div><script>async function j(path){return(await fetch(path)).json()}async function load(){document.querySelector('#cluster').textContent=JSON.stringify(await j('/v1/cluster'),null,2);const objects=await j('/v1/objects');const detail=await Promise.all(objects.map(o=>j('/v1/objects/'+encodeURIComponent(o.Key)+'?metadata=1')));document.querySelector('#objects').textContent=JSON.stringify(detail,null,2);for(const x of ['repairs','events'])document.querySelector('#'+x).textContent=JSON.stringify(await j('/v1/'+x),null,2)}async function act(x,body){await fetch('/v1/admin/'+x,{method:'POST',body:body&&JSON.stringify(body)});load()}function partition(){let id=prompt('Node ID');let enabled=confirm('Enable partition? Cancel disables');act('nodes/'+id+'/partition',{enabled})}function corrupt(){let id=prompt('Node ID');let key=prompt('Object key');let version=+prompt('Version');act('nodes/'+id+'/corrupt',{key,version})}setInterval(load,2000);load()</script>`
